        opposite[face[2]] = face[4];
        opposite[face[4]] = face[2];

        for (int i = 0; i < 7; i++) next_dp[i] = -1000000;

        for (int bottom = 1; bottom <= 6; bottom++) {
            int top = opposite[bottom];
            int side_max = 0;

            for (int i = 0; i < 6; i++) {
                if (face[i] != bottom && face[i] != top && face[i] > side_max)
                    side_max = face[i];
            }

            if (die == 0) {
                next_dp[top] = side_max;
            } else if (dp[bottom] > -1000000) {
                int candidate = dp[bottom] + side_max;
                if (candidate > next_dp[top]) next_dp[top] = candidate;
